    ["zero_encoder_delta"] = "no event",
    ["large_encoder_delta"] = "E1 sign only, one transition; other encoders preserve owner delta semantics",
    ["key_edges"] = "K1/K2/K3 down/up are exactly what norns delivers to script key(n,z) (mosaic.lua:318, ui.lua:66). norns keeps a short K1 tap for itself and toggles the system menu; the script only receives K1 edges of a held K1, so K1.down/K1.up are modifier edges and are never blocked. K1.short and native.return are not key events: see emission.",
    ["grid_outcome"] = "Notification after the original handler; never repeat its mutation. One resolved outcome sets state.context, state.screen and state.target in one step (outcome.follow). A navigation retain flow never navigates; its screen names the inspector for the full result. An alternative may override navigation and context.",
    ["emission"] = {
      ["authority"] = "The router wraps m_grid g.key (lib/m_grid.lua:240-287), g.remove (290-310), script key() and the redraw clock. Each event is emitted after the original handler of its phase returns; a handler is never re-run and an outcome is never inferred from later state.",
      ["rows"] = {
        {
          ["phase"] = "grid down, after press:handle_pre",
          ["when"] = "key is a hold-scope step of the current page and the presentation held set was empty",
          ["emits"] = "hold.begin",
          ["payload"] = "steps = ordered runtime held set",
        },
        {
          ["phase"] = "grid down, after press:handle_pre",
          ["when"] = "hold-scope step and the held set was not empty",
          ["emits"] = "hold.change",
          ["payload"] = "steps",
        },
        {
          ["phase"] = "long timer, after press:handle_long (m_grid.lua:362-367)",
          ["when"] = "a registered long handler resolved an outcome",
          ["emits"] = "grid.outcome",
          ["payload"] = "flow_id, target, page, mode branch",
        },
        {
          ["phase"] = "grid up, after press:handle short (m_grid.lua:279)",
          ["when"] = "always when a flow resolved",
          ["emits"] = "grid.outcome",
        },
        {
          ["phase"] = "grid up, after press:handle_dual (m_grid.lua:275)",
          ["when"] = "the release that fires the dual handler, whichever key is released first",
          ["emits"] = "grid.outcome",
        },
        {
          ["phase"] = "grid up, after press:handle_post (every release, claimed keys included)",
          ["when"] = "released key was in the held set and the set is still not empty",
          ["emits"] = "hold.change",
        },
        {
          ["phase"] = "grid up, after press:handle_post",
          ["when"] = "no grid key remains pressed and this gesture emitted hold.begin or a temporary grid.outcome",
          ["emits"] = "hold.end",
        },
        {
          ["phase"] = "g.remove after runtime post handlers",
          ["when"] = "always",
          ["emits"] = "grid.disconnect",
        },
        {
          ["phase"] = "script key(n,z)",
          ["when"] = "always",
          ["emits"] = "K1.down/K1.up/K2.*/K3.* as delivered",
        },
        {
          ["phase"] = "redraw clock tick (mosaic.lua:252-259) and every dispatch",
          ["when"] = "norns menu mode observed false->true",
          ["emits"] = "K1.short",
        },
        {
          ["phase"] = "redraw clock tick and every dispatch",
          ["when"] = "norns menu mode observed true->false",
          ["emits"] = "native.return",
        },
      },
      ["forbid"] = {
        "grid.outcome from a pre or post handler",
        "more than one grid.outcome per handler phase",
        "hold.end before the grid.outcome of the same release",
        "a page change without the grid.outcome of G01-G04",
      },
      ["order_per_release"] = "short or dual handler -> grid.outcome -> post handlers -> hold.change or hold.end",
    },
